51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** Dedicated audit logger; emits an audit line on successful owner create. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final AddressNormalizer addressNormalizer;
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper,
91	                                 TelephoneNormalizer telephoneNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.addressNormalizer = addressNormalizer;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
135	        LocalDate registrationDate = owner.getRegistrationDate();
136	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
137	            .map(Owner::getRegistrationDate)
138	            .filter(registrationDate::equals)
139	            .count();
140	        if (ownersCreatedThatDay >= 100) {
141	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
142	        }
143	        String address = addressNormalizer.normalize(owner.getAddress());
144	        if (address.isBlank()) {
145	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
146	        }
147	        owner.setAddress(address);
148	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
149	        if (telephone == null) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        owner.setTelephone(telephone);
156	        String email = owner.getEmail();
157	        if (email != null) {
158	            email = email.trim();
159	            if (!EMAIL_PATTERN.matcher(email).matches()) {
160	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	            }
162	            String emailKey = email.toLowerCase(Locale.ROOT);
163	            owner.setEmail(emailKey);
164	            boolean emailInUse = this.clinicService.findAllOwners().stream()
165	                .map(Owner::getEmail)
166	                .filter(Objects::nonNull)
167	                .map(existing -> existing.trim().toLowerCase(Locale.ROOT))
168	                .anyMatch(emailKey::equals);
169	            if (emailInUse) {
170	                return new ResponseEntity<>(HttpStatus.CONFLICT);
171	            }
172	        }
173	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
174	            .map(Owner::getTelephone)
175	            .filter(Objects::nonNull)
176	            .map(telephoneNormalizer::normalize)
177	            .anyMatch(telephone::equals);
178	        if (telephoneInUse) {
179	            return new ResponseEntity<>(HttpStatus.CONFLICT);
180	        }
181	        String cityKey = normalizeIdentity(owner.getCity());
182	        long ownersInCity = this.clinicService.findAllOwners().stream()
183	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
184	            .count();
185	        if (ownersInCity >= 50) {
186	            return new ResponseEntity<>(HttpStatus.CONFLICT);
187	        }
188	        String lastNameKey = normalizeIdentity(owner.getLastName());
189	        String addressKey = addressNormalizer.normalize(owner.getAddress());
190	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
191	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
192	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
193	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
194	            if (householdDuplicate) {
195	                return new ResponseEntity<>(HttpStatus.CONFLICT);
196	            }
197	        }
198	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
199	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
200	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
201	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
202	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
203	            .count();
204	        owner.setNamesakeCount(namesakeCount);
205	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
206	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
207	        this.clinicService.saveOwner(owner);
208	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
209	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
210	            ownerMapper.membershipLevel(owner));
211	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
215	    }
216	
217	    /**
218	     * Normalize a value for household-identity comparison: null becomes an empty
219	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
220	     * to a single space, and the result is lower-cased.
221	     */
222	    private static String normalizeIdentity(String value) {
223	        if (value == null) {
224	            return "";
225	        }
226	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
227	    }
228	
229	    /**
230	     * Build the stable, shared household identifier for an owner, formatted
231	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
232	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
233	     * Owners in the same household (same normalized lastName and address) therefore
234	     * derive an identical householdId.
235	     */
236	    private static String householdId(String lastNameKey, String addressKey) {
237	        String source = lastNameKey + "|" + addressKey;
238	        try {
239	            byte[] digest = MessageDigest.getInstance("SHA-256")
240	                .digest(source.getBytes(StandardCharsets.UTF_8));
241	            StringBuilder sb = new StringBuilder(digest.length * 2);
242	            for (byte b : digest) {
243	                sb.append(String.format("%02x", b));
244	            }
245	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
246	        }
247	        catch (NoSuchAlgorithmException e) {
248	            throw new IllegalStateException("SHA-256 not available", e);
249	        }
250	    }
251	
252	    /**
253	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
254	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
255	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
256	     * sequence equal to one more than the number of owners already in that city
257	     * (e.g. 'LON-SMI-0007').
258	     */
259	    private String nextCustomerCode(String city, String lastName) {
260	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
261	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
262	        String cityKey = normalizeIdentity(city);
263	        int sequence = (int) this.clinicService.findAllOwners().stream()
264	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
265	            .count() + 1;
266	        return String.format("%s-%s-%04d", city3, last3, sequence);
267	    }
268	
269	    /**
270	     * Roll a registration date forward to the next business day: a Saturday or Sunday
271	     * advances to the following Monday, and a weekday is returned unchanged.
272	     */
273	    private static LocalDate toBusinessDay(LocalDate date) {
274	        return switch (date.getDayOfWeek()) {
275	            case SATURDAY -> date.plusDays(2);
276	            case SUNDAY -> date.plusDays(1);
277	            default -> date;
278	        };
279	    }
280	
281	    /**
282	     * Build the membership number assigned on create, formatted
283	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
284	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
285	     */
286	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
287	        String yy = String.format("%02d", registrationDate.getYear() % 100);
288	        return customerCode + "-M" + yy;
289	    }
290	
291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
294	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
295	        if (currentOwner == null) {
296	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
297	        }
298	        currentOwner.setAddress(ownerFieldsDto.getAddress());
299	        currentOwner.setCity(ownerFieldsDto.getCity());
300	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
301	        currentOwner.setLastName(ownerFieldsDto.getLastName());
302	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
303	        this.clinicService.saveOwner(currentOwner);
304	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
305	    }
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Transactional
309	    @Override
310	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner == null) {
313	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
314	        }
315	        this.clinicService.deleteOwner(owner);
316	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
322	        Owner owner = this.clinicService.findOwnerById(ownerId);
323	        if (owner == null) {
324	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	        }
326	        HttpHeaders headers = new HttpHeaders();
327	        Pet pet = petMapper.toPet(petFieldsDto);
328	        owner.setId(ownerId);
329	        pet.setOwner(owner);
330	        pet.getType().setName(null);
331	        this.clinicService.savePet(pet);
332	        PetDto petDto = petMapper.toPetDto(pet);
333	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
334	            .buildAndExpand(pet.getId()).toUri());
335	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
336	    }
337	
338	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
339	    @Override
340	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
341	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
342	        if (currentOwner != null) {
343	            Pet currentPet = this.clinicService.findPetById(petId);
344	            if (currentPet != null) {
345	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
346	                currentPet.setName(petFieldsDto.getName());
347	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
348	                this.clinicService.savePet(currentPet);
349	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
350	            }
351	        }
352	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
358	        HttpHeaders headers = new HttpHeaders();
359	        Visit visit = visitMapper.toVisit(visitFieldsDto);
360	        Pet pet = new Pet();
361	        pet.setId(petId);
362	        visit.setPet(pet);
363	        this.clinicService.saveVisit(visit);
364	        VisitDto visitDto = visitMapper.toVisitDto(visit);
365	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
366	            .buildAndExpand(visit.getId()).toUri());
367	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
368	    }
369	
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Override
373	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
374	        Owner owner = this.clinicService.findOwnerById(ownerId);
375	        if (owner != null) {
376	            Pet pet = owner.getPet(petId);
377	            if (pet != null) {
378	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
379	            }
380	        }
381	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
382	    }
383	}
