17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Map;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Normalises a raw telephone number to the single canonical form under which it is both
25	 * stored and compared for duplicates.
26	 *
27	 * <p>Keeping this in one place means the stored form and the form used to detect duplicate
28	 * telephones can never drift apart: an owner is a duplicate of another exactly when their
29	 * telephones normalise to the same value.
30	 *
31	 * <p>The canonical form is E.164: a leading '+' followed by 8 to 15 digits. A number that
32	 * already carries a leading '+' keeps its explicit country code; otherwise country code
33	 * '+61' is assumed and a single leading '0' is dropped from the national digits. Spaces,
34	 * dashes and brackets are stripped. Anything that cannot reduce to a '+' plus 8 to 15 digits
35	 * has no canonical form.
36	 */
37	@Component
38	public class TelephoneNormalizer {
39	
40	    private static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    private static final int MIN_DIGITS = 8;
43	
44	    private static final int MAX_DIGITS = 15;
45	
46	    /**
47	     * Country code (the digits after the '+') to the exact number of national digits an
48	     * E.164 telephone for that country must carry. Australia ('+61') requires 9 national
49	     * digits and the North American Numbering Plan ('+1') requires 10. A country code not
50	     * listed here carries no per-country length constraint beyond the generic E.164 range.
51	     */
52	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
53	
54	    /**
55	     * Reduce a raw telephone to its canonical E.164 stored form.
56	     *
57	     * @param rawTelephone the telephone as supplied by the client, possibly {@code null} or
58	     *                     containing spaces, dashes or brackets
59	     * @return the canonical E.164 telephone (a '+' followed by 8 to 15 digits), or
60	     *         {@code null} if {@code rawTelephone} cannot form a valid E.164 number
61	     */
62	    public String normalize(String rawTelephone) {
63	        if (rawTelephone == null) {
64	            return null;
65	        }
66	        String trimmed = rawTelephone.trim();
67	        boolean hasCountryCode = trimmed.startsWith("+");
68	        String digits = trimmed.replaceAll("\\D", "");
69	        if (!hasCountryCode) {
70	            if (digits.startsWith("0")) {
71	                digits = digits.substring(1);
72	            }
73	            digits = DEFAULT_COUNTRY_CODE + digits;
74	        }
75	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
76	            return null;
77	        }
78	        return "+" + digits;
79	    }
80	
81	    /**
82	     * Whether a canonical E.164 telephone carries the national-number length its country
83	     * code requires. Country code '+61' requires 9 national digits and '+1' requires 10;
84	     * the national number is the digits that follow the country code. A number whose
85	     * country code has no pinned length is not constrained beyond the generic E.164 range.
86	     *
